/**
 * Baut den Payload fuer POST /api/webhooks/offer.
 *
 * Wichtigste Aenderung gegenueber dem alten Flow: jede Quelle wird EXPLIZIT
 * ueber $('Node') gelesen. Vorher liefen Ticket, Account und Hausverwaltung
 * durch einen Merge (combineByPosition). Alle drei Zoho-Antworten haben "data"
 * auf oberster Ebene — die Schluessel kollidierten, und die nachgeladenen
 * Datensaetze fielen still unter den Tisch (daher kunde.name: "").
 */

// ---------- Helfer ----------
const txt = (v) => (v === null || v === undefined ? '' : String(v).trim());

/** Zahl mit Standardwert. 0 bleibt 0 (nicht wie "|| 20" still auf den Default). */
const zahl = (v, standard) => {
  if (v === null || v === undefined || v === '') return standard;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : standard;
};

/** Zoho-Lookups kommen mal als {id, name}, mal als reiner String. */
const lookupName = (v) => {
  if (!v) return '';
  if (typeof v === 'string') return v.trim();
  if (typeof v === 'object') return txt(v.name || v.Name || v.Account_Name);
  return '';
};

/**
 * Erster Datensatz eines Zoho-Nodes — oder null, wenn der Node nichts,
 * einen Fehler oder eine leere Antwort geliefert hat. Genau diese Toleranz
 * ersetzt den Merge: eine tote Nebenabfrage kostet nur ihr eigenes Feld.
 */
const zohoRecord = (nodeName) => {
  try {
    const j = $(nodeName).first().json;
    const rec = j && Array.isArray(j.data) ? j.data[0] : null;
    return rec && rec.id ? rec : null;
  } catch (e) {
    return null;
  }
};

/** Heute in Wiener Zeit — UTC waere zwischen 00:00 und 02:00 der Vortag. */
const heute = () => {
  try {
    return DateTime.now().setZone('Europe/Vienna').toISODate();
  } catch (e) {
    return new Date().toISOString().slice(0, 10);
  }
};

// ---------- Quellen ----------
const hookBody = ($('Webhook').first().json || {}).body || {};

const ticket = zohoRecord('Ticket laden');
if (!ticket) {
  throw new Error(
    'Ticket ' + (txt(hookBody.ticketId) || '(ohne ID)') +
    ' konnte nicht aus Zoho geladen werden — Angebot wird NICHT angelegt.'
  );
}

// Beide Nebenabfragen duerfen fehlschlagen (Lookup leer, Zoho-Aussetzer).
const objektAccount = zohoRecord('Kunde laden');
const hausverwaltung = zohoRecord('Hausverwaltung laden');

const ticketId = txt(ticket.id) || txt(hookBody.ticketId);
const ticketNummer = txt(ticket.Name) || txt(hookBody.ticketNumber);
if (!ticketId) {
  throw new Error('TicketID fehlt — ohne sie erkennt die Plattform Wiederholungen nicht.');
}

// ---------- Objekt / Gasse ----------
// "Staettermayergasse 22, 1150 Wien" -> Strasse / PLZ / Ort
const gassenName = lookupName(ticket.Kunde_Gasse) || txt(objektAccount && objektAccount.Account_Name);

let objStrasse = '';
let objPlz = '';
let objOrt = '';
const teile = gassenName.split(',');
if (teile.length >= 2) {
  objStrasse = teile[0].trim();
  const rest = teile.slice(1).join(',').trim();
  const m = /^(\d{4,5})\s+(.+)$/.exec(rest);
  if (m) {
    objPlz = m[1];
    objOrt = m[2].trim();
  } else {
    objOrt = rest;
  }
} else if (gassenName) {
  objStrasse = gassenName;
}

// Luecken aus dem Account-Datensatz fuellen — der wird jetzt endlich benutzt.
objStrasse = objStrasse || txt(objektAccount && objektAccount.Billing_Street);
objPlz = objPlz || txt(objektAccount && objektAccount.Billing_Code) || txt(ticket.Bezirk);
objOrt = objOrt || txt(objektAccount && objektAccount.Billing_City);

// ---------- Rechnungsempfaenger ----------
const hvName =
  txt(hausverwaltung && hausverwaltung.Name) ||
  txt(hausverwaltung && hausverwaltung.Hausverwaltung) ||
  txt(hausverwaltung && hausverwaltung.Account_Name) ||
  lookupName(ticket.Zust_ndige_Hausverwaltung);

const accountName = lookupName(ticket.Account_Name) || txt(objektAccount && objektAccount.Account_Name);

// Reihenfolge wie resolveKundeName() in der Plattform: HV -> Account -> Gasse.
// ansprechpartner ist NIE der Kunde, sondern die/der interne MitarbeiterIn.
const kundeName = hvName || accountName || gassenName;

const rgStrasse =
  txt(ticket.Rechnungsadresse_Strasse) ||
  txt(hausverwaltung && (hausverwaltung.Billing_Street || hausverwaltung.Strasse)) ||
  txt(objektAccount && objektAccount.Billing_Street);
const rgPlz =
  txt(ticket.Rechnungsadresse_PLZ) ||
  txt(hausverwaltung && (hausverwaltung.Billing_Code || hausverwaltung.PLZ)) ||
  txt(objektAccount && objektAccount.Billing_Code);
const rgOrt =
  txt(ticket.Rechnungsadresse_Stadt) ||
  txt(hausverwaltung && (hausverwaltung.Billing_City || hausverwaltung.Ort)) ||
  txt(objektAccount && objektAccount.Billing_City);

const uid =
  txt(ticket.USt_ID) ||
  txt(hausverwaltung && (hausverwaltung.USt_ID || hausverwaltung.UID)) ||
  txt(objektAccount && objektAccount.USt_ID);

const kunde = {
  name: kundeName,
  strasse: rgStrasse,
  plz: rgPlz,
  ort: rgOrt,
  land: 'Österreich',
  ansprechpartner: txt(ticket.Ticket_erstellt_von),
  email:
    txt(ticket.E_Mail) ||
    txt(ticket.Email) ||
    txt(ticket.Rechnungs_E_Mail) ||
    txt(hausverwaltung && hausverwaltung.Email),
  emailAngebot: txt(ticket.E_Mail) || txt(hausverwaltung && hausverwaltung.Email),
  emailRechnung: txt(ticket.Rechnungs_E_Mail),
  uidnummer: uid,
  uidVonHI: txt(ticket.UID_von_HI),
  rechnungAnHI: Boolean(ticket.Rechnung_an_HI),
  telefon:
    txt(ticket.Ansprechperson_Tel) ||
    txt(ticket.Phone) ||
    txt(hausverwaltung && hausverwaltung.Phone),
  ustId: uid,
  objektAdresse: {
    gasse: gassenName,
    strasse: objStrasse,
    plz: objPlz,
    ort: objOrt,
    bezirk: txt(ticket.Bezirk),
  },
};

// ---------- Steuer ----------
// Beides kommt aus dem Zoho-Body; Deluge rechnet es dort bereits aus.
// Der alte Flow hat es verworfen und JEDES Angebot mit 20 % angelegt —
// bei Reverse Charge also mit falscher Steuer.
const reverseCharge =
  hookBody.reverseCharge === true ||
  String(hookBody.reverseCharge).toLowerCase() === 'true' ||
  String(ticket.Reverse_Charge).toLowerCase() === 'true';
const ustSatz = reverseCharge ? 0 : zahl(hookBody.steuerWert, 20);

// ---------- Positionen ----------
const dlRoh = ticket.Dienstleistung_en;
const dienstleistungen = Array.isArray(dlRoh)
  ? dlRoh.map(txt).filter(Boolean)
  : (txt(dlRoh) ? [txt(dlRoh)] : []);

// Preise aus dem Deluge-Quote uebernehmen, falls dort welche stehen.
const quoteZeilen = Array.isArray(hookBody.quote && hookBody.quote.Product_Details)
  ? hookBody.quote.Product_Details
  : [];

const positionen = dienstleistungen.map((dl, i) => {
  const q = quoteZeilen[i] || {};
  return {
    pos: i + 1,
    produktName: dl,
    // Bewusst leer: die Plattform setzt "produktName\nbeschreibung" zusammen,
    // ein "X fuer Gasse Y" unter der Ueberschrift "X" stand doppelt im PDF.
    // Das Objekt steht ohnehin im Belegkopf (objekt_bezeichnung).
    beschreibung: '',
    menge: zahl(q.quantity, 1),
    einheit: 'Stk',
    einzelpreisNetto: Math.max(0, zahl(q.list_price, 0)),
    rabattProzent: 0,
    ustSatz: ustSatz,
  };
});

if (positionen.length === 0) {
  const q = quoteZeilen[0] || {};
  positionen.push({
    pos: 1,
    produktName: 'Dienstleistung',
    beschreibung: gassenName ? 'Arbeiten für ' + gassenName : 'Arbeiten laut Ticket',
    menge: zahl(q.quantity, 1),
    einheit: 'Stk',
    einzelpreisNetto: Math.max(0, zahl(q.list_price, 0)),
    rabattProzent: 0,
    ustSatz: ustSatz,
  });
}

// ---------- Angebot ----------
const angebot = {
  // Angebotsdatum = Erstellungstag. Vorher stand hier ticket.Startdatum, also
  // der geplante Arbeitsbeginn — daraus haette die Plattform auch die
  // Gueltigkeit gerechnet.
  datum: heute(),
  // gueltigBis bewusst NICHT gesetzt: die Plattform setzt zwei Monate ab
  // Angebotsdatum (gueltigBisDefault). Der alte Flow schrieb 30 Tage und
  // ueberschrieb damit den fachlichen Standard.
  erstelltDurch: lookupName(ticket.Owner),
  geschaeftsfallnummer: txt(ticket.Gesch_ftsfallnummer),
  bemerkung: [
    txt(ticket.Angebotsbemerkung),
    txt(ticket.Dienstleistung_Zusatz),
    txt(ticket.Description),
  ].filter(Boolean).join(' | '),
  skizzenLink:
    txt(ticket.Skizzen_Link) ||
    txt(ticket.Fotos_Ordnerlink) ||
    txt(ticket.Angebot_Link) ||
    txt(ticket.Workdrive_Link),
  objektBeschreibung: gassenName,
  dienstleistungen: dienstleistungen,
  reverseCharge: reverseCharge,
};

// ---------- Payload ----------
const vermittler = ticket.Vermittler_von_Ticket || null;

const payload = {
  source: 'zoho',
  entityType: 'ticket',
  ticketId: ticketId,
  ticketNumber: ticketNummer,
  kunde: kunde,
  angebot: angebot,
  positionen: positionen,
  meta: {
    workdriveFolderId: txt(ticket.Workdrive_ID) || txt(ticket.Foto_Ordner_ID),
    // callbackUrl bewusst entfernt: die alte zeigte auf /webhook-test/ einer
    // anderen n8n-Instanz. Die Plattform ruft sie synchron auf und wartete
    // jedes Mal auf einen toten Endpunkt.
    quellen: {
      kundeGeladen: Boolean(objektAccount),
      hausverwaltungGeladen: Boolean(hausverwaltung),
    },
    zoho: {
      ownerId: txt(ticket.Owner && ticket.Owner.id),
      ownerEmail: txt(ticket.Owner && ticket.Owner.email),
      ownerName: lookupName(ticket.Owner),
      ticketErstelltVon: txt(ticket.Ticket_erstellt_von),
      kundeGasseId: txt(ticket.Kunde_Gasse && ticket.Kunde_Gasse.id),
      kundeGasseName: gassenName,
      accountName: accountName,
      hausverwaltungId:
        txt(hausverwaltung && hausverwaltung.id) ||
        txt(ticket.Zust_ndige_Hausverwaltung && ticket.Zust_ndige_Hausverwaltung.id),
      hausverwaltungName: hvName,
      kundenTyp: txt(ticket.Kunden_Typ),
      hausinhabung: txt(ticket.Hausinhabung_HI),
      vermittler: vermittler
        ? { id: txt(vermittler.id), name: lookupName(vermittler) }
        : null,
      projektstatus: txt(ticket.Projektstatus),
      startdatum: txt(ticket.Startdatum),
      enddatum: txt(ticket.Enddatum),
      auftragssumme: zahl(ticket.Auftragssumme, 0),
      bezirk: txt(ticket.Bezirk),
      layoutId: txt(ticket.Layout && ticket.Layout.id),
      preislistenTyp: txt(ticket.Preislisten_Typ),
      standortZuweisung: txt(ticket.Standort_Zuweisung),
      workdriveLink: txt(ticket.Workdrive_Link),
      fotosOrdnerlink: txt(ticket.Fotos_Ordnerlink),
      angeboteOrdnerlink: txt(ticket.Angebote_Ordnerlink),
      rechnungenOrdnerlink: txt(ticket.Rechnungen_Ordnerlink),
      lat: ticket.Lat === undefined ? null : ticket.Lat,
      lng: ticket.Lng === undefined ? null : ticket.Lng,
      mapsLink: txt(ticket.Maps_Link),
    },
  },
};

return [{ json: payload }];
